<script lang="ts">
 import photo0 from '../../../../../2.jpg';import photo1 from '../../../../../3.jpg';import photo2 from '../../../../../4.jpg';import photo3 from '../../../../../1.jpg';
 import ProductMockup from './ProductMockup.svelte';import type { BaselineCopy } from './copy';import type { Locale } from '../data/translations';
 let {c,locale}:{c:BaselineCopy;locale:Locale}=$props();let active=$state(0);const photos=[photo0,photo1,photo2,photo3];
 function key(event:KeyboardEvent,index:number){let next=index;if(event.key==='ArrowRight')next=(index+1)%4;else if(event.key==='ArrowLeft')next=(index+3)%4;else if(event.key==='Home')next=0;else if(event.key==='End')next=3;else return;event.preventDefault();active=next;document.getElementById(`b-tab-${next}`)?.focus();}
</script>
<section id="solutions" class="b-section" data-section="5" aria-labelledby="b-cases-heading"><div class="b-wrap"><p class="b-eyebrow">{c.nav[1]}</p><h2 id="b-cases-heading" class="b-heading">{c.casesTitle}</h2><div class="b-case-tabs" role="tablist" aria-label={c.nav[1]}>{#each c.caseTabs as tab,i (tab)}<button id={`b-tab-${i}`} role="tab" aria-selected={active===i} aria-controls={`b-case-${i}`} tabindex={active===i?0:-1} onclick={()=>active=i} onkeydown={e=>key(e,i)}>{tab}<span>0{i+1}</span></button>{/each}</div>{#each c.product.cases as item,i (item[0])}<div id={`b-case-${i}`} role="tabpanel" aria-labelledby={`b-tab-${i}`} tabindex="0" hidden={active!==i} class="b-case-panel b-panel"><div class="b-case-photo"><img src={photos[i]} alt={c.caseTabs[i]} loading="lazy"/><span>{c.caseTabs[i]} / RAHUNOK</span></div><div class="b-case-content"><h3>{item[1]}</h3><p>{item[2]}</p><ol>{#each item.slice(3) as line (line)}<li>{line}</li>{/each}</ol></div><div class="b-case-mock"><ProductMockup {c} {locale} variant={i} compact amount={[490,1250,1800,2400][i]}/></div></div>{/each}</div></section>